    static let coachRecruitReturnBf = SmallCases.make(
        key: "story.followup.coachRecruitReturnBf",
        category: .whiteCollar,
        headlines: ["Former Coach Linked to a Second College's Recruit List", "Prior Bribery Case Resurfaces at a New School"],
        law: "bribery",
        spec: "Corruptly accepted a thing of value as a public official, on {DATE}.",
        ages: 28...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a former coach now at another school listed students as recruits for $45,000. {DL} says the funds were booster donations.",
        state: [E(.digital, 3, "Booster Emails", "Prices for roster spots."), E(.document, 2, "Roster File", "Recruits who never played.")],
        defense: [E(.document, 1, "Booster Receipts", "Receipts for gym equipment.")],
        role: "Compliance officer",
        exam: [.direct("What is your position?", "\"I'm a compliance officer for the conference that oversees athletic programs at local schools.\""), .direct("What did you investigate?", "\"A coach, {DL}, who had moved to another school, and who was accused of selling spots on a team roster.\""), .direct("What did you find in the booster emails?", "\"Emails quoting prices for roster spots, ranging from two thousand to five thousand dollars, sent to parents.\""), .direct("What does the roster file show?", "\"Students listed as recruits who never played a game, and some who never attended practice.\""), .direct("How much was collected?", "\"About forty-five thousand dollars over two seasons, according to the bank deposits.\""), .direct("What did {DL} say?", "\"{D.He} said the money was booster donations that were used for equipment and travel.\""), .cross("Boosters do raise money?", "\"Yes, and it's normal, but not in exchange for roster spots.\""), .cross("Receipts exist for gym equipment?", "\"Some do, though they cover only a fraction of the money.\""), .cross("Parents knew the prices?", "\"Some did, and they said they paid to get their children on the team.\""), .cross("{DL} was a successful coach?", "\"Yes, with good records, which is why parents trusted {D.him}.\""), .cross("{DL} cooperated?", "\"With some of my requests, though not with all of the records I asked for.\"")],
        theory: ("{D} sold spots again.", "Booster gifts."),
        allocution: "\"I coached for many years, and I never sold a spot on any roster. That money came from boosters who wanted to support the program, and I handled it as a donation. I understand the compliance office sees it differently, and I respect their duty to check. I'd ask the court to look at the booster records before deciding I sold anything.\"",
        truths: ("{DL} had a prior case in this court.", "Equipment really was bought."),
        defendant: [.direct("Did you sell roster spots?", "\"No. Parents donated money to the booster club, and I never promised a spot in return.\""), .direct("What about the emails with prices?", "\"They were suggestions for donation amounts. I wasn't selling anything.\""), .direct("Why were some students listed as recruits who never played?", "\"Some left the team or got injured. The roster was never updated.\""), .direct("Where did the money go?", "\"To equipment, travel, uniforms, and tournament fees. I have receipts for much of it.\""), .direct("Did you keep any for yourself?", "\"A small amount, for expenses that I never reported. I know that was wrong.\""), .direct("What would you tell the parents and the conference?", "\"I'm sorry for the confusion and the harm. I'll cooperate with a full audit.\""), .cross("You were investigated at your last school for something similar, weren't you?", "\"Yes, and I was cleared. I'm not that kind of coach.\""), .cross("The emails quote prices for spots?", "\"They do say that, and I understand how the emails read to a parent or an investigator.\""), .cross("You didn't report the money you kept?", "\"I didn't report the money I kept, and that was a serious mistake on my part.\""), .cross("You'll give the conference your records?", "\"Yes, I'll hand the conference all of my records, bank statements, and email accounts.\""), .cross("You'll step down from coaching?", "\"If the conference says so, yes, I'll step down from coaching and stay away from athletics.\"")],
        openings: ("A compliance officer for the conference that oversees athletic programs at local schools found that {D}, a coach who had moved to another school, was accused of selling spots on a team roster, with booster emails listing prices and a roster file naming recruits who never played, totaling $45,000, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say the funds were booster donations spent on gym equipment, and {D} has the receipts. A donation is not a sale of a spot."),
        closings: ("The booster emails give prices for roster spots, the roster file shows recruits who never played, and having faced {PRIOR} before, {DL} understood exactly what the conference rules forbid.", "Booster donations spent on equipment are lawful, and receipts show where they went. The State must prove {D} sold roster spots, and the receipts for gym equipment show where the money went."),
        timeline: [(-45, "The booster dinner."), (0, "The cash."), (60, "The audit.")],
        identified: "Booster Emails",
        mood: .wantsConviction)

    static let festivalAgainBf = SmallCases.make(
        key: "story.followup.festivalAgainBf",
        category: .whiteCollar,
        headlines: ["Promoter Sells Tickets to a New Festival Months After a Failed One", "Prior Festival Promoter Faces Refund Claims Again"],
        law: "falsePretenses100k",
        spec: "Obtained over $100,000 by false pretenses from {V} and others, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a promoter sold $160,000 in tickets to a food festival that never opened. {DL} says a venue canceled.",
        state: [E(.digital, 3, "Ticket Sales", "$160,000 in a month."), E(.document, 2, "Venue Emails", "No signed contract.")],
        defense: [E(.document, 1, "Venue Notice", "A cancellation notice.")],
        role: "Ticket buyer",
        exam: [.direct("What did you buy?", "\"Tickets to a food festival that was advertised for the summer, with chefs, music, and tastings, and I paid seventy dollars each for four tickets.\""), .direct("How were the tickets sold?", "\"Through an online page run by {DL}, who called {D.himself} the festival's promoter and promised a big event.\""), .direct("What happened?", "\"A week before the festival, an email said it was postponed. Then it was canceled, and there was no refund.\""), .direct("How much was sold?", "\"About one hundred sixty thousand dollars in tickets over a month, according to the ticket sales records.\""), .direct("What do the venue emails show?", "\"That there was never a signed contract with the venue, only a few exchanges about a possible date.\""), .direct("What did {DL} say?", "\"{D.He} said the venue canceled and that {D.he} couldn't help it.\""), .cross("The festival was widely advertised?", "\"Yes, on social media and on posters around the county.\""), .cross("{DL} posted updates?", "\"A few, but they were vague and never said what the new plan was.\""), .cross("{DL} has promised refunds?", "\"Yes, many times, but nothing has ever come, and the messages stopped.\""), .cross("You know others who bought tickets?", "\"Yes, dozens of people, including several of my neighbors, lost money on tickets.\""), .cross("You've contacted the venue?", "\"Yes, I called them, and they said they never agreed to host any festival.\"")],
        theory: ("{D} sold another fake event.", "A venue canceled."),
        allocution: "\"I truly planned to open that festival, and I sold tickets because I expected the venue to hold. When it canceled, I was left scrambling, and I never meant to keep anyone's money. I know our agreement was only verbal, and that was a mistake. I'm sorry to every family that bought tickets, and I've always planned to refund them.\"",
        truths: ("{DL} had a prior case in this court.", "The notice is dated after the sales."),
        defendant: [.direct("Did you take money for a festival that didn't happen?", "\"I took money for a festival I hoped to hold. The venue backed out, and I couldn't make it happen.\""), .direct("Did you have a contract?", "\"Not a signed one. I had emails and a verbal promise, and I thought that was enough.\""), .direct("Why did you keep selling tickets?", "\"I believed I'd find another venue. I kept selling because I was sure it would work out.\""), .direct("Where did the money go?", "\"Advertising, deposits for vendors, and my own bills. I spent more than I should have.\""), .direct("Why didn't you refund buyers?", "\"I didn't have the money. I'd spent it, and I was afraid and ashamed.\""), .direct("What would you tell the ticket buyers?", "\"I'm sorry for the lost money and the lost festival. I'll repay as much as I can.\""), .cross("You've been convicted of taking money for an event before, haven't you?", "\"Yes, and the court told me to be honest. I wasn't.\""), .cross("You sold tickets before you had a venue?", "\"I did sell tickets before I had a venue, and I know that's wrong.\""), .cross("A cancellation notice from the venue exists?", "\"It does, but it came after I sold most of the tickets.\""), .cross("You'll repay a hundred sixty thousand dollars?", "\"I'll repay what I can, on a payment plan that the court and the buyers approve.\""), .cross("You'll stop promoting events?", "\"Yes, I'll stop promoting events of any kind and I'll find honest work.\"")],
        openings: ("{V} bought four tickets at $70 each to a food festival that was advertised for the summer with chefs, music and tastings, through an online page run by {D}, who called {D.himself} the festival's promoter, and ticket sales reached $160,000 in a month though venue emails show no signed contract, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the venue canceled at the last minute, and {D} could not hold the festival. A cancellation notice is in evidence."),
        closings: ("The ticket sales are $160,000 in a month, no contract was ever signed with the venue, and since {PRIOR}, {DL} could not have missed what selling tickets to an unbooked event means.", "A venue canceled, and {D} did not know it would. The State must prove {D} never meant to hold the festival, and a cancellation notice shows the plan failed through no fault of {D.his}."),
        timeline: [(-45, "Sales open."), (0, "Event day."), (10, "Charges.")],
        identified: "Ticket Sales",
        mood: .wantsConviction)

    static let teamClaimAgainBf = SmallCases.make(
