        category: .publicOrder,
        headlines: ["Student With Prior False Report Accuses Another Team", "Door Camera Again Contradicts the Claim"],
        law: "falseReport",
        spec: "Made a false report to a law enforcement agency, on {DATE}.",
        ages: 18...24,
