        defense: [E(.statement, 1, "Memory", "{DL} says the night is blurry.")],
        role: "Campus officer",
        exam: [.direct("What is your position?", "\"I'm a campus police officer, and I investigate reports at the university, including student-event incidents.\""), .direct("What did the student report?", "\"That {DL} was assaulted at a team event the night before, with injuries to {D.his} face and ribs.\""), .direct("What did you check?", "\"Cameras at the door of the building where the event was held, and a group chat among the team members.\""), .direct("What does the door camera show?", "\"{DL} walking in and out of the building at the time of the claimed assault, with no one touching or attacking {D.him}.\""), .direct("What does the group chat show?", "\"Messages among teammates joking about the claim, saying nothing happened that night.\""), .direct("What did {DL} say?", "\"{D.He} said the night was blurry and that {D.he} might be mistaken.\""), .cross("The student had been drinking?", "\"Yes, according to several teammates, though {DL} denies drinking that evening.\""), .cross("The student did have a bruise?", "\"A small bruise on the cheek, which could have come from many causes.\""), .cross("{DL} reported it right away?", "\"The report came the next morning, after {D.he} woke up at a friend's apartment.\""), .cross("{DL} was upset?", "\"Yes, {D.he} was quite emotional when {D.he} came to the station, and cried several times.\""), .cross("{DL} withdrew the claim?", "\"Yes, {D.he} withdrew the claim once I showed {D.him} the door camera video.\"")],
        theory: ("{D} made a false report.", "A blurry memory."),
        allocution: "\"I told the officer what I remembered from that night, and I truly believed it happened. There are gaps in my memory, and I understand the cameras don't show the room. I didn't mean to cause trouble for the team or for anyone on it. I'm sorry for the investigation it set off, and for the people who were questioned.\"",
        truths: ("{DL} had a prior case in this court.", "Friends heard a scream."),
        defendant: [.direct("Did you make a false report?", "\"I reported what I thought had happened, but I may have been wrong. The night is blurry for me.\""), .direct("Why did you think you were attacked?", "\"I woke up with a bruise and a sore side, and I didn't remember how I got them.\""), .direct("Did you drink that night?", "\"Yes, more than I should have. I don't remember much after the party began.\""), .direct("Why did the chat joke about it?", "\"They think I made it up. They don't understand how scared I felt.\""), .direct("What did you do when shown the video?", "\"I said I must have been wrong, and I withdrew the report.\""), .direct("What would you tell the officers and the team?", "\"I'm sorry for the trouble and for blaming anyone. I should have waited until I remembered more.\""), .cross("You were warned about a false report before, weren't you?", "\"Yes, and I promised to be careful. I let my fear get ahead of the facts.\""), .cross("The video shows no one touching you?", "\"It doesn't show anyone touching me, and I accept that now that I've seen it.\""), .cross("Your report accused other students?", "\"It did name other students, and I'm sorry for that, because they didn't deserve it.\""), .cross("You'll apologize to the team?", "\"Yes, I'll apologize to the team in person, if they're willing to hear it.\""), .cross("You'll get help with drinking?", "\"Yes, I've already signed up for counseling, and I'll go every week without missing.\"")],
        openings: ("A campus police officer investigating reports at the university took a report from {D} that {D} had been assaulted at a team event the night before, with injuries to {D.his} face and ribs, but the door camera shows no one being attacked and the group chat has messages joking about it, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say the night is blurry and {D} did not know what had happened, only that {D.he} was hurt. {D} did not mean to lie."),
        closings: ("The door camera shows no attack, the group chat jokes about it, and after {PRIOR} {DL} understood exactly what a false report costs.", "A blurry memory is not a lie, and {D} did report real injuries. The State must prove {D} knew the report was false."),
        timeline: [(0, "Party."), (1, "The report."), (5, "Review.")],
        identified: "Door Camera",
        mood: .divided,
        genders: ["D": .female])

    static let deviceDriverAgainBf = SmallCases.make(
        key: "story.followup.deviceDriverAgainBf",
        category: .violent,
        headlines: ["Delivery Driver Forced to Drive With a Device; Suspect Linked to Prior Case", "Second Delivery Driver Held in a Fake Bomb Scheme"],
        law: "kidnapping2",
        spec: "Unlawfully confined, restrained and removed {V} for the purpose of facilitating a felony, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a delivery driver says {D} strapped a device to {V} and ordered a drive to a bank. {DL} says it was a prop given in a game.",
        state: [E(.video, 3, "Bank Camera", "{V} walks in wearing a vest."), E(.forensic, 2, "Device", "A fake device.")],
        defense: [E(.statement, 1, "Game", "{DL} says it was a dare.")],
        role: "Bomb technician",
        exam: [.direct("What is your position?", "\"I'm a bomb technician with the sheriff's office, and I examine suspicious devices.\""), .direct("What was reported?", "\"A delivery driver said a man strapped a device to {V.his} chest and ordered {V.him} to drive to a bank.\""), .direct("What does the bank camera show?", "\"{V} walking into the bank wearing a vest with a device, looking terrified, and handing a note to a teller.\""), .direct("What did you find when you examined the device?", "\"A fake device, made of wires, batteries, and a timer that didn't connect to any explosive.\""), .direct("Who was identified as the man?", "\"{DL}, from a license plate on the delivery truck and a witness who saw {D.him} with {V}.\""), .direct("What did {DL} say?", "\"{D.He} said it was a dare and a prop from a game, and that {D.he} never meant to harm anyone.\""), .cross("The device couldn't explode?", "\"No, it was a prop, but {V} didn't know that.\""), .cross("{DL} wasn't armed?", "\"No weapon was found on {D.him} when {D.he} was searched, and {D.he} didn't resist.\""), .cross("{V} wasn't hurt physically?", "\"No, {V.he} wasn't physically hurt, but {V.he} was terrified and shaking when I saw {V.him}.\""), .cross("{DL} waited outside the bank?", "\"Yes, {D.he} waited outside in a car, and deputies arrested {D.him} there.\""), .cross("{DL} told you where the prop came from?", "\"{D.He} said a friend gave the prop to {D.him} for a game, but didn't say who.\"")],
        theory: ("{D} held a driver hostage.", "A dare."),
        allocution: "\"I did strap that device on the driver, but it was a prop we used in a game, and I never ordered anyone to drive to a bank. I can see how frightening it must have looked to the driver, and I'm deeply sorry for that fear. It was a stupid way to play. I never meant to hurt or rob anyone.\"",
        truths: ("{DL} had a prior case in this court.", "The vest was bought online."),
        defendant: [.direct("Did you strap the device on the driver?", "\"I put a vest on {V.him}, but it was a prop. I told him it was part of a game.\""), .direct("What game was it?", "\"A dare among friends. We said we'd make someone play along, and it went too far.\""), .direct("Did you threaten the driver?", "\"I told him to drive to the bank, and I told him it was a game. {V.He} didn't seem to think so.\""), .direct("Why did you want him to go to the bank?", "\"Part of the dare was to see if he'd hand a note to the teller. I never planned to take money.\""), .direct("What did you do when you saw the driver was scared?", "\"I felt sick, and I waited outside for the deputy. I didn't try to run.\""), .direct("What would you tell the driver?", "\"I'm sorry for scaring you so badly. I never meant to hurt you, and I'll pay for any counseling.\""), .cross("You've been charged with something like this before, haven't you?", "\"Yes, and I told the court I'd stay out of trouble. I broke that promise.\""), .cross("A man wearing a vest with a device looks like a bomb threat, doesn't he?", "\"{V.He} does look like a bomber, and I see that now, though I didn't think of it.\""), .cross("You forced the driver to follow orders?", "\"I did order {V.him} around, and I regret it more than I can say.\""), .cross("You'll pay for the driver's counseling?", "\"Yes, I'll pay for the driver's counseling for as long as he needs it.\""), .cross("You'll stay away from the driver?", "\"Yes, entirely. I won't contact the driver or go near the places he works.\"")],
        openings: ("A bomb technician with the sheriff's office examined a device that a delivery driver said a man strapped to {V.his} chest while ordering {V.him} to drive to a bank, and the bank camera shows {V} walk in wearing a vest, and the device was a fake, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say it was a prop given in a game, a dare among friends, and {D} never meant to force anyone to a bank. {D} meant it as a joke."),
        closings: ("The bank camera shows {V} walking in wearing a vest, the device was strapped to {V.him}, and with {PRIOR} behind {D.him}, {DL} knew what that does to a driver.", "A prop given in a game is not a hostage plan. The State must prove {D} meant {V} to believe the device was real."),
        timeline: [(0, "Delivery."), (0, "Bank."), (1, "Arrest.")],
        identified: "Bank Camera",
        mood: .wantsConviction)

    static let lotteryAgainBf = SmallCases.make(
        key: "story.followup.lotteryAgainBf",
