        defense: [E(.statement, 1, "Gift", "{DL} says {V} said keep it.")],
        role: "Lottery investigator",
        exam: [.direct("What is your position?", "\"I'm an investigator for the state lottery, and I look into claims that seem suspicious.\""), .direct("What was the claim?", "\"A clerk at a convenience store claimed a one hundred eighty thousand dollar winning ticket that had been sold to a customer.\""), .direct("Who claimed the ticket?", "\"{DL}, the clerk, who signed the claim form and presented the original ticket.\""), .direct("What does the store camera show?", "\"The customer buying the ticket, scratching it, and leaving it on the counter without realizing it was a winner.\""), .direct("What happened next?", "\"{DL} picked up the ticket after the customer left, looked at it, and put it in a pocket.\""), .direct("What did {DL} say?", "\"{D.He} said the customer told {D.him} to keep it, but the video shows no conversation.\""), .cross("The customer didn't know the ticket won?", "\"No, {V.he} thought it was a loser and walked out.\""), .cross("{DL} claimed the ticket days later?", "\"Yes, about a week after the sale, after thinking about it for days.\""), .cross("{DL} could have told the customer?", "\"Yes, {D.he} could have told the customer, but {D.he} didn't say a word.\""), .cross("The ticket was signed on the back by {DL}?", "\"Yes, {D.he} signed the back after the claim, which is what the form requires.\""), .cross("The customer discovered it later?", "\"{V.He} saw a news story about the winner and recognized the ticket.\"")],
        theory: ("{D} kept a winning ticket.", "A gift."),
        allocution: "\"A customer gave me that ticket as a gift, and I never asked for it. I redeemed it believing it was mine to claim. I understand why the lottery investigators questioned it, and I'm sorry for the confusion it caused. I'm not a greedy person, and I'd gladly sort out the matter with the customer.\"",
