        exam: [.direct("What is your assignment?", "\"I'm a detective, and I investigate online crimes, including extortion and websites that demand money.\""), .direct("What was reported?", "\"Over twenty people told us that a website was showing their arrest photos and demanding money to take them down.\""), .direct("How much was demanded?", "\"Four hundred dollars per photo, in most cases, with threats that the photos would stay online forever.\""), .direct("What do the removal invoices show?", "\"Demands from twenty people, all with the same pattern, the same price, and the same payment instructions.\""), .direct("What do the domain records show?", "\"That the site was newly created, but registered to the same owner as an earlier site that was shut down, {DL}.\""), .direct("What did {DL} say?", "\"{D.He} said the fees were for a legal removal service and that people were free to refuse.\""), .cross("The photos are public records?", "\"Many are, but publishing them with a payment demand is another matter.\""), .cross("The site has a terms page?", "\"Yes, there is a page that says the fees are for editorial services, which doesn't fit.\""), .cross("Some victims paid?", "\"Yes, about ten people paid, for about four thousand dollars in total.\""), .cross("{DL} removed photos after payment?", "\"Some were removed, though they appeared again on other pages that {D.he} controlled.\""), .cross("{DL} cooperated?", "\"Partly, but {D.he} wouldn't give me all of {D.his} records.\"")],
